mapper.select:
SELECT CA.*, M.MEMBER_NAME, M.MEMBER_ID, M.MEMBER_NICKNAME FROM COACH_APPLY CA JOIN MEMBER M ON CA.MEMBER_NO = M.MEMBER_NO WHERE 1=1
AND CA.COA_YN = #{status}
AND (M.MEMBER_NAME LIKE '%' || #{searchKeyword} || '%' OR M.MEMBER_ID LIKE '%' || #{searchKeyword} || '%')
AND TO_CHAR(CA.APPLY_DATE, 'YYYY-MM-DD') = #{applyDate}
ORDER BY CA.APPLY_DATE DESC
